using System;
using System.Collections.Generic;

namespace Framework.Parameters
{
    /// <summary>
    /// パラメーターの識別子、初期値および有効範囲を定義する。
    /// </summary>
    /// <typeparam name="TParameter">
    /// パラメーターを識別する型。
    /// </typeparam>
    /// <remarks>
    /// 定義情報は生成後に変更できない。
    /// 実行時の値や補正情報は別のクラスで管理する。
    /// 識別子には不変の値型やenumの使用を推奨する。
    /// </remarks>
    public sealed class ParameterDefinition<TParameter>
    {
        /// <summary>
        /// パラメーターの識別子を取得する。
        /// </summary>
        public TParameter Id { get; }

        /// <summary>
        /// パラメーターの標準初期値を取得する。
        /// </summary>
        public float DefaultValue { get; }

        /// <summary>
        /// パラメーターの最小許容値を取得する。
        /// </summary>
        public float MinValue { get; }

        /// <summary>
        /// パラメーターの最大許容値を取得する。
        /// </summary>
        public float MaxValue { get; }

        /// <summary>
        /// 最小値と最大値が等しい固定値の定義かどうかを取得する。
        /// </summary>
        public bool IsFixedValue => MinValue == MaxValue;

        /// <summary>
        /// パラメーターの定義を生成する。
        /// </summary>
        /// <param name="id">パラメーターの識別子</param>
        /// <param name="defaultValue">標準初期値</param>
        /// <param name="minValue">最小許容値</param>
        /// <param name="maxValue">最大許容値</param>
        /// <exception cref="ArgumentNullException">
        /// 識別子がnullの場合に発生する。
        /// </exception>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 数値が有限値ではない場合、
        /// または初期値が有効範囲外の場合に発生する。
        /// </exception>
        /// <exception cref="ArgumentException">
        /// 最小値が最大値を上回る場合に発生する。
        /// </exception>
        public ParameterDefinition(
            TParameter id,
            float defaultValue,
            float minValue,
            float maxValue)
        {
            // 識別子がnullでないことを確認する。
            if (id is null)
            {
                throw new ArgumentNullException(nameof(id));
            }

            // 各数値が有限値であることを確認する。
            ValidateFiniteValue(defaultValue, nameof(defaultValue));
            ValidateFiniteValue(minValue, nameof(minValue));
            ValidateFiniteValue(maxValue, nameof(maxValue));

            // 有効範囲の大小関係を確認する。
            if (minValue > maxValue)
            {
                throw new ArgumentException(
                    "最小値は最大値以下である必要があります。",
                    nameof(minValue));
            }

            // 初期値が有効範囲内に存在することを確認する。
            if (defaultValue < minValue || defaultValue > maxValue)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(defaultValue),
                    "初期値が有効範囲外です。");
            }

            Id = id;
            DefaultValue = defaultValue;
            MinValue = minValue;
            MaxValue = maxValue;
        }

        /// <summary>
        /// 指定された値が有効範囲内に存在するか判定する。
        /// </summary>
        /// <param name="value">判定対象の値</param>
        /// <returns>
        /// 有限値かつ有効範囲内の場合はtrue。
        /// それ以外の場合はfalse。
        /// </returns>
        public bool IsInRange(float value)
        {
            if (float.IsNaN(value) || float.IsInfinity(value))
            {
                return false;
            }

            return value >= MinValue && value <= MaxValue;
        }

        /// <summary>
        /// 指定された値を有効範囲内に制限する。
        /// </summary>
        /// <param name="value">制限対象の値</param>
        /// <returns>有効範囲内に制限された値</returns>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 指定された値が有限値ではない場合に発生する。
        /// </exception>
        public float Clamp(float value)
        {
            ValidateFiniteValue(value, nameof(value));

            if (value < MinValue)
            {
                return MinValue;
            }

            if (value > MaxValue)
            {
                return MaxValue;
            }

            return value;
        }

        /// <summary>
        /// 指定された値を有効範囲に対する0から1の値に正規化する。
        /// </summary>
        /// <param name="value">正規化対象の値</param>
        /// <returns>
        /// 0から1の正規化値。
        /// 固定値の定義の場合は0。
        /// </returns>
        /// <remarks>
        /// 有効範囲外の値は制限してから正規化する。
        /// </remarks>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 指定された値が有限値ではない場合に発生する。
        /// </exception>
        public float Normalize(float value)
        {
            // 固定値の場合も不正な数値を検証する。
            float clampedValue = Clamp(value);

            if (IsFixedValue)
            {
                return 0f;
            }

            // 中間計算のオーバーフローを防ぐためdoubleを使用する。
            double range = (double)MaxValue - MinValue;
            double offset = (double)clampedValue - MinValue;

            return (float)(offset / range);
        }

        /// <summary>
        /// 0から1の正規化値を実際のパラメーター値に変換する。
        /// </summary>
        /// <param name="normalizedValue">正規化された値</param>
        /// <returns>有効範囲に対応するパラメーター値</returns>
        /// <remarks>
        /// 0未満の値は0、1を超える値は1として扱う。
        /// </remarks>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 指定された値が有限値ではない場合に発生する。
        /// </exception>
        public float Denormalize(float normalizedValue)
        {
            ValidateFiniteValue(
                normalizedValue,
                nameof(normalizedValue));

            if (normalizedValue <= 0f)
            {
                return MinValue;
            }

            if (normalizedValue >= 1f)
            {
                return MaxValue;
            }

            // 有効範囲に対する線形補間を行う。
            double range = (double)MaxValue - MinValue;

            return (float)(MinValue + range * normalizedValue);
        }

        /// <summary>
        /// 指定された識別子が自身の識別子と一致するか判定する。
        /// </summary>
        /// <param name="id">比較対象の識別子</param>
        /// <returns>識別子が一致する場合はtrue</returns>
        public bool MatchesId(TParameter id)
        {
            return EqualityComparer<TParameter>.Default.Equals(
                Id,
                id);
        }

        /// <summary>
        /// 指定された値が有限値であることを検証する。
        /// </summary>
        /// <param name="value">検証対象の値</param>
        /// <param name="parameterName">引数名</param>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 値がNaNまたは無限大の場合に発生する。
        /// </exception>
        private static void ValidateFiniteValue(
            float value,
            string parameterName)
        {
            if (float.IsNaN(value) || float.IsInfinity(value))
            {
                throw new ArgumentOutOfRangeException(
                    parameterName,
                    "有限値を指定してください。");
            }
        }
    }
}
